import ast, sys

def enclosing(path, lines):
    src = open(path).read()
    tree = ast.parse(src)
    res = {}
    def walk(node, stack):
        for child in ast.iter_child_nodes(node):
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                newstack = stack + [child.name]
                for ln in lines:
                    if child.lineno <= ln <= child.end_lineno:
                        cur = res.get(ln)
                        if cur is None or len(newstack) > len(cur):
                            res[ln] = newstack
                walk(child, newstack)
            else:
                walk(child, stack)
    walk(tree, [])
    return res

path = sys.argv[1]
lines = [int(x) for x in sys.argv[2:]]
r = enclosing(path, lines)
for ln in lines:
    print(ln, r.get(ln))
